/* ====================================================================== *
 *  Water surface pass (full screen ray-cast)
 * ====================================================================== */
const CRATER_N = 12;
const surfU = Object.assign({}, SU, {
  tUnder: { value: null }, uInvVP: { value: new THREE.Matrix4() }, uW2U: { value: new THREE.Vector2(0.05, 0.05) },
  uCrat: { value: Array.from({ length: CRATER_N }, () => new THREE.Vector4()) }, uWhirl: { value: new THREE.Vector4(0, 0, 0, 0) },
  uSimTexel: { value: new THREE.Vector2(1 / 440, 1 / 440) }
});
const surfMat = passMat(GLSL_COMMON + `
uniform sampler2D tUnder, tSim; uniform mat4 uInvVP; uniform vec4 uDomain; uniform vec2 uSimCell, uSimTexel, uW2U, uTargetRes;
uniform float uTime, uSun, uRain; uniform vec3 uSunDir; uniform vec4 uCrat[${CRATER_N}]; uniform vec4 uWhirl;
varying vec2 vUv;
vec3 sky(vec3 r){
  float y = max(r.y, 0.0);
  vec3 c = mix(vec3(0.80,0.90,0.97), vec3(0.26,0.53,0.90), pow(y, 0.55));
  vec2 cp = r.xz / (r.y + 0.18) * 1.3 + uTime * vec2(0.010, 0.005);
  float cl = smoothstep(0.52 - uRain*0.3, 0.86, fbm3(cp));
  c = mix(c, vec3(0.98) * (1.0 - 0.35*uRain), cl * 0.85);
  c = mix(c, vec3(0.62,0.66,0.70), uRain*0.55);
  float s = max(dot(r, uSunDir), 0.0);
  c += vec3(1.0,0.92,0.75) * pow(s, 80.0) * 0.6 * uSun;
  return c;
}
void main(){
  vec2 ndc = vUv * 2.0 - 1.0;
  vec4 a = uInvVP * vec4(ndc, -1.0, 1.0); a /= a.w;
  vec4 b = uInvVP * vec4(ndc, 1.0, 1.0); b /= b.w;
  vec3 rd = normalize(b.xyz - a.xyz);
  float t = -a.y / rd.y;
  vec3 p = a.xyz + rd * t;
  vec2 suv = (p.xz - uDomain.xy) / uDomain.zw;
  vec2 o = uSimTexel * 1.5;
  vec4 sc = texture2D(tSim, suv);
  float hl = texture2D(tSim, suv - vec2(o.x, 0.0)).r, hr = texture2D(tSim, suv + vec2(o.x, 0.0)).r;
  float hd = texture2D(tSim, suv - vec2(0.0, o.y)).r, hu = texture2D(tSim, suv + vec2(0.0, o.y)).r;
  vec2 grad = vec2(hr - hl, hu - hd) / (2.0 * uSimCell * 1.5) * 0.6;
  // whirlpool twist of the wind pattern
  vec2 wp = p.xz;
  vec2 wd = p.xz - uWhirl.xy; float wr = length(wd); float ws = uWhirl.z;
  if (ws > 0.001) {
    float ang = ws * 3.2 / (wr * 0.7 + 0.5);
    float cs = cos(ang), sn = sin(ang);
    wp = uWhirl.xy + mat2(cs, sn, -sn, cs) * wd;
  }
  float windAmt = 1.0 + uRain * 0.7;
  vec3 n1 = noised(wp * 1.5 + vec2(uTime * 0.32, uTime * 0.21));
  vec3 n2 = noised(mat2(0.8, 0.6, -0.6, 0.8) * wp * 3.3 - vec2(uTime * 0.47, -uTime * 0.29));
  vec3 n3 = noised(wp * 7.1 + vec2(-uTime * 0.75, uTime * 0.55));
  grad += (n1.yz * 1.5 * 0.045 + n2.yz * 3.3 * 0.02 + n3.yz * 7.1 * 0.0085) * windAmt;
  grad += vec2(0.035 * cos(p.x * 0.45 + p.z * 0.2 + uTime * 0.9), 0.025 * cos(p.z * 0.37 - uTime * 0.7));
  // splash craters: short-lived analytic bowls (only ever brighten)
  float bright = 0.0, foamA = 0.0;
  for (int i = 0; i < ${CRATER_N}; i++) {
    vec4 c = uCrat[i];
    if (c.w > 0.0) {
      vec2 d = p.xz - c.xy; float dl = length(d);
      float R = c.w * (0.55 + 0.75 * sqrt(c.z));
      float r = dl / R;
      if (r < 1.7) {
        float fade = 1.0 - c.z; fade *= fade;
        vec2 dir = d / (dl + 1e-4);
        float slope = (r < 1.0 ? r * 1.7 : -(1.7 - r) * 1.3) * fade;
        grad += dir * slope;
        bright += fade * (0.42 * (1.0 - r * r) * step(r, 1.0) + 0.55 * exp(-(r - 1.0) * (r - 1.0) * 26.0));
        foamA += fade * exp(-(r - 1.0) * (r - 1.0) * 16.0) * (0.5 + 0.6 * vnoise(d * 5.0 + c.xy));
      }
    }
  }
  // whirlpool funnel + spiral foam arms
  if (ws > 0.001) {
    float R0 = 1.1;
    float q = 1.0 + wr * wr / (R0 * R0);
    float dh = ws * 2.6 * 2.0 * wr / (R0 * R0) / (q * q);
    grad += wd / (wr + 1e-3) * dh;
    float ang = atan(wd.y, wd.x);
    float arm = sin(ang * 3.0 + log(wr + 0.05) * 5.5 - uTime * 2.6);
    float arm2 = sin(ang * 5.0 + log(wr + 0.05) * 7.0 - uTime * 3.4 + 1.3);
    foamA += ws * (smoothstep(0.45, 1.0, arm) + 0.5 * smoothstep(0.7, 1.0, arm2)) * smoothstep(5.8, 1.6, wr) * smoothstep(0.15, 0.7, wr)
           * (0.5 + 0.6 * vnoise(wd * 3.0 + uTime * 0.7));
  }
  vec3 n = normalize(vec3(-grad.x, 1.0, -grad.y));
  // refraction of the underwater scene
  vec2 uv = vUv;
  float dA = texture2D(tUnder, uv).a;
  float depth = dA / 0.22;
  vec2 off = vec2(n.x, -n.z) * (0.12 + depth * 0.26) * uW2U;
  vec3 refr;
  refr.r = texture2D(tUnder, uv + off * 1.00).r;
  refr.g = texture2D(tUnder, uv + off * 1.06).g;
  refr.b = texture2D(tUnder, uv + off * 1.12).b;
  vec2 bo = (0.6 + dA * 3.0) / uTargetRes;
  vec2 uvb = uv + off * 1.06;
  vec3 bl = (texture2D(tUnder, uvb + vec2(bo.x, bo.y)).rgb + texture2D(tUnder, uvb + vec2(-bo.x, bo.y)).rgb
           + texture2D(tUnder, uvb + vec2(bo.x, -bo.y)).rgb + texture2D(tUnder, uvb + vec2(-bo.x, -bo.y)).rgb) * 0.25;
  refr = mix(refr, bl, clamp(dA * 0.9, 0.0, 0.6));
  // fresnel sky reflection
  float cosi = clamp(dot(-rd, n), 0.0, 1.0);
  float F = 0.02 + 0.98 * pow(1.0 - cosi, 5.0);
  vec3 R = reflect(rd, n);
  vec3 col = mix(refr, sky(R), F);
  // sun glints
  vec3 ng = normalize(n + vec3(n3.y, 0.0, n3.z) * 0.06);
  vec3 Rg = reflect(rd, ng);
  float sd = max(dot(Rg, uSunDir), 0.0);
  col += vec3(1.0, 0.96, 0.86) * (pow(sd, 1400.0) * 26.0 + pow(sd, 160.0) * 0.55 + pow(sd, 18.0) * 0.05) * uSun * (1.0 - uRain * 0.8);
  // foam
  float foam = sc.b * 0.85 + foamA;
  float fnz = vnoise(p.xz * 9.0 + uTime * 0.3) * 0.6 + vnoise(p.xz * 23.0 - uTime * 0.2) * 0.4;
  float fm = smoothstep(0.22, 0.85, foam * (0.5 + 0.95 * fnz));
  col = mix(col, vec3(0.96, 0.985, 1.0) * (0.86 + 0.14 * uSun), clamp(fm, 0.0, 0.92));
  col += bright * vec3(0.55, 0.74, 0.78);
  if (ws > 0.001) col = mix(col, col * vec3(0.80, 0.92, 1.0), ws * exp(-wr * wr * 0.7) * 0.5);
  col *= 1.0 - 0.10 * uRain;
  // mild tone curve
  col = col * 1.05 / (1.0 + 0.05 * col);
  vec3 cc = clamp(col, 0.0, 1.0);
  col = mix(col, cc * cc * (3.0 - 2.0 * cc), 0.14);
  gl_FragColor = vec4(col, 1.0);
}`, surfU);

/* ====================================================================== *
 *  Creature shaders
 * ====================================================================== */
const CR_VS = `
attribute vec4 aInfo; attribute vec4 aHinge;
attribute vec3 iPos; attribute vec4 iQuat; attribute vec4 iA; attribute vec4 iB; attribute vec4 iC;
uniform float uSpecies, uWaveMode, uWaveK, uHalfZ;
uniform sampler2D tSim; uniform vec4 uDomain; uniform vec3 uSunW;
varying vec3 vRest; varying vec3 vRestN; varying vec4 vInfo; varying vec3 vW; varying vec3 vN;
varying float vAlpha; varying float vWet; varying float vWaterH; varying float vShade;
vec3 qrot(vec4 q, vec3 v){ return v + 2.0 * cross(q.xyz, cross(q.xyz, v) + q.w * v); }
float uOf(float x){ return clamp(0.5 - x, 0.0, 1.35); }
float waveF(float x){ float u = uOf(x); return iA.y * (0.12 + 0.88 * u * u) * sin(iA.x - 6.2831853 * uWaveK * u); }
float turnF(float x){ float u = uOf(x); return iA.z * u * u * 0.35; }
float archF(float x){ float u = uOf(x); return iB.z * (u - 0.5) * (u - 0.5); }
float floorApprox(vec2 xz){ float t = clamp(0.5 - xz.y / (2.0 * uHalfZ), 0.0, 1.0); return -(1.35 + 2.95 * (t * 0.85 + 0.15 * t * t)); }
void main(){
  vec3 p = position; vec3 n = normal;
  // flippers / pectorals rotate on hinges about the body axis
  if (aHinge.w > 0.0) {
    float side = aInfo.w;
    float rear = step(4.5, aInfo.x) * step(aInfo.x, 5.5);
    float ph = iA.w + rear * 1.7;
    float flap = mix(iC.w + iB.w * sin(ph), iC.w * 0.3 + iB.w * 0.6 * sin(ph), rear);
    float ang = -side * flap * aHinge.w;
    vec3 d = p - aHinge.xyz;
    float ca = cos(ang), sa = sin(ang);
    d = vec3(d.x, d.y * ca - d.z * sa, d.y * sa + d.z * ca);
    n = vec3(n.x, n.y * ca - n.z * sa, n.y * sa + n.z * ca);
    if (uSpecies > 4.5 && uSpecies < 5.5) {
      float ay = side * 0.55 * cos(ph) * aHinge.w * min(iB.w * 2.0, 1.0) * (1.0 - rear * 0.5);
      float cy = cos(ay), sy = sin(ay);
      d = vec3(d.x * cy + d.z * sy, d.y, -d.x * sy + d.z * cy);
      n = vec3(n.x * cy + n.z * sy, n.y, -n.x * sy + n.z * cy);
    }
    p = aHinge.xyz + d;
  }
  // manta wing beat travelling outward, amplitude ~ |z|^1.45
  if (uSpecies > 5.5 && aInfo.x < 7.5) {
    float az = abs(p.z) + 1e-4;
    float ph = iA.w - 2.4 * az;
    float s = sin(ph), c = cos(ph);
    float pw = pow(az, 1.45);
    p.y += iB.w * s * pw * 0.6;
    float dw = iB.w * 0.6 * (-2.4 * c * pw + s * 1.45 * pow(az, 0.45)) * sign(p.z);
    n = vec3(n.x, n.y, n.z - dw * n.y);
  }
  // spine: swimming wave + turn curvature + arch; sections stay perpendicular
  float x = p.x, e = 0.012;
  float fz = turnF(x), fy = archF(x);
  float dz = (turnF(x + e) - turnF(x - e)) / (2.0 * e);
  float dy = (archF(x + e) - archF(x - e)) / (2.0 * e);
  if (uWaveMode > 0.5 && uWaveMode < 1.5) { fz += waveF(x); dz += (waveF(x + e) - waveF(x - e)) / (2.0 * e); }
  else if (uWaveMode > 1.5) { fy += waveF(x); dy += (waveF(x + e) - waveF(x - e)) / (2.0 * e); }
  float a = atan(dz), b = atan(dy);
  float sa = sin(a), ca = cos(a), sb = sin(b), cb = cos(b);
  vec3 q = vec3(x - p.z * sa - p.y * sb, fy + p.y * cb, fz + p.z * ca);
  vec3 nn = vec3(n.x * ca - n.z * sa, n.y, n.x * sa + n.z * ca);
  nn = vec3(nn.x * cb - nn.y * sb, nn.x * sb + nn.y * cb, nn.z);
  vec3 wp = iPos + qrot(iQuat, q * iB.x);
  vRest = position; vRestN = normal; vInfo = aInfo; vAlpha = iB.y; vWet = iC.z;
  vW = wp; vN = qrot(iQuat, nn);
  float wh = 0.0;
#ifdef USE_VTF
  wh = texture2D(tSim, (wp.xz - uDomain.xy) / uDomain.zw).r;
#endif
  vWaterH = wh;
  vShade = 1.0;
#ifdef SHADOW
  vec3 L = uSunW;
  float f0 = floorApprox(wp.xz);
  vec3 sp = wp - L * ((wp.y - f0) / L.y);
  float f1 = floorApprox(sp.xz);
  sp = wp - L * ((wp.y - f1) / L.y);
  vShade = clamp(1.15 - (wp.y - f1) * 0.14, 0.3, 1.0);
  gl_Position = projectionMatrix * viewMatrix * vec4(sp.x, f1, sp.z, 1.0);
#else
  gl_Position = projectionMatrix * viewMatrix * vec4(wp, 1.0);
#endif
}`;

const CR_FS = GLSL_COMMON + `
uniform float uSpecies, uTime, uSun; uniform vec4 uEye; uniform vec3 uCam, uSunDir, uSunW; uniform sampler2D tCaust;
varying vec3 vRest; varying vec3 vRestN; varying vec4 vInfo; varying vec3 vW; varying vec3 vN;
varying float vAlpha; varying float vWet; varying float vWaterH; varying float vShade;
vec4 voroV(vec2 x){ vec2 n = floor(x), f = fract(x); float m1 = 8.0, m2 = 8.0; vec2 mr = vec2(0.0); float id = 0.0;
  for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) { vec2 g = vec2(float(i), float(j));
    vec2 o = 0.5 + 0.32 * (vec2(hash12(n + g), hash12(n + g + 19.7)) - 0.5) * 2.0; vec2 r = g + o - f; float d = dot(r, r);
    if (d < m1) { m2 = m1; m1 = d; mr = r; id = hash12(n + g + 3.3); } else if (d < m2) { m2 = d; } }
  return vec4(mr, sqrt(m2) - sqrt(m1), id); }
bool isPart(float p, float k){ return abs(p - k) < 0.5; }

vec3 colShark(float part, vec3 r, vec4 info, vec3 nl, inout float gloss){
  gloss = 0.7;
  vec3 slate = vec3(0.34, 0.39, 0.44), white = vec3(0.93, 0.93, 0.91);
  float n = vnoise(r.xz * 45.0 + r.y * 20.0);
  if (isPart(part, 0.0)) {
    float top = info.z;
    float line = -0.12 + 0.22 * (vnoise(vec2(r.x * 26.0, 1.7)) - 0.5) + 0.05 * sin(r.x * 95.0 + 1.3) - 0.10 * smoothstep(0.15, 0.45, r.x);
    vec3 c = mix(white, slate * (0.92 + 0.12 * n), smoothstep(line - 0.03, line + 0.03, top));
    c *= mix(1.0, 0.82, smoothstep(0.1, 0.9, top));
    if (r.x > 0.16 && r.x < 0.27 && abs(info.w) > 0.3 && top > -0.35 && top < 0.5) {
      float g = abs(fract((r.x - 0.16) / 0.022) - 0.5);
      c *= mix(0.42, 1.0, smoothstep(0.05, 0.16, g));
    }
    return c;
  }
  if (isPart(part, 2.0)) {
    if (nl.y < 0.0) return mix(white, vec3(0.10, 0.11, 0.12), smoothstep(0.70, 0.86, info.z));
    return slate * 0.88 * (0.95 + 0.1 * n);
  }
  return slate * (0.84 + 0.12 * n);
}
vec3 colHammer(float part, vec3 r, vec4 info, vec3 nl, inout float gloss){
  gloss = 0.6;
  vec3 bronze = vec3(0.52, 0.48, 0.40), pale = vec3(0.90, 0.88, 0.82);
  float n = vnoise(r.xz * 40.0 + r.y * 10.0);
  if (isPart(part, 0.0)) { float line = -0.25 + 0.06 * sin(r.x * 40.0); return mix(pale, bronze * (0.9 + 0.14 * n), smoothstep(line - 0.08, line + 0.08, info.z)); }
  if (isPart(part, 6.0)) return mix(pale, bronze * (0.9 + 0.12 * n), smoothstep(-0.2, 0.15, info.z));
  if (isPart(part, 2.0)) return nl.y > 0.0 ? bronze * 0.95 : mix(pale, bronze * 0.7, smoothstep(0.75, 0.95, info.z));
  return bronze * (0.86 + 0.12 * n);
}
vec3 colHump(float part, vec3 r, vec4 info, vec3 nl, inout float gloss){
  gloss = 0.8;
  vec3 dark = vec3(0.07, 0.08, 0.10), white = vec3(0.90, 0.90, 0.88);
  float n = vnoise(r.xz * 30.0 + r.y * 9.0);
  float mott = smoothstep(0.38, 0.62, vnoise(r.xz * vec2(18.0, 26.0) + 3.0) * 0.7 + vnoise(r.xz * 60.0) * 0.3);
  if (isPart(part, 0.0)) {
    float top = info.z;
    float belly = smoothstep(-0.12, -0.42, top) * smoothstep(-0.45, -0.2, r.x);
    vec3 bc = mix(white, dark * 1.6, mott * 0.6);
    vec3 c = mix(dark * (0.9 + 0.2 * n), bc, belly);
    if (top < -0.25 && r.x > -0.08) { float pl = abs(sin(r.z * 150.0 + sin(r.x * 20.0) * 0.6)); c *= mix(0.5, 1.0, smoothstep(0.0, 0.35, pl)); }
    if (r.x > 0.30 && top > 0.1) { vec3 v = voro(vec2(r.x * 55.0, r.z * 55.0)); float k = 1.0 - smoothstep(0.10, 0.28, v.x);
      c = mix(c, vec3(0.30, 0.30, 0.31), k * step(0.4, v.z)); }
    c = mix(c, vec3(0.55), smoothstep(0.93, 0.98, vnoise(r.xz * vec2(80.0, 6.0))) * 0.4 * step(0.0, top));
    return c;
  }
  if (isPart(part, 2.0)) {
    vec3 c = white * (0.92 + 0.08 * n);
    if (nl.y > 0.0) c = mix(c, dark * 1.5, mott * 0.65 * smoothstep(0.65, 0.0, info.z));
    return c;
  }
  if (isPart(part, 3.0)) {
    if (nl.y > 0.0) return dark * (0.9 + 0.2 * n);
    vec3 c = mix(white, dark, mott * 0.7); return mix(c, dark, smoothstep(0.80, 0.95, info.y));
  }
  return dark * (0.9 + 0.2 * n);
}
vec3 colOrca(float part, vec3 r, vec4 info, vec3 nl, inout float gloss){
  gloss = 0.95;
  vec3 blk = vec3(0.035, 0.037, 0.045), wht = vec3(0.95, 0.95, 0.93);
  if (isPart(part, 0.0)) {
    float top = info.z, x = r.x, side = abs(info.w);
    float w = smoothstep(-0.30, -0.52, top) * smoothstep(-0.12, 0.04, x);
    w = max(w, smoothstep(-0.02, -0.30, top) * smoothstep(0.40, 0.45, x));
    w = max(w, smoothstep(-0.62, -0.82, top) * smoothstep(-0.36, -0.18, x));
    vec2 fl = vec2((x + 0.13) / 0.13, (top + 0.22 - (-x - 0.13) * 1.4) / 0.30);
    w = max(w, 1.0 - smoothstep(0.82, 1.0, length(fl)));
    vec2 ep = vec2((x - 0.315) / 0.065, (top - 0.40) / 0.15);
    w = max(w, (1.0 - smoothstep(0.80, 1.0, length(ep))) * step(0.2, side));
    vec3 c = mix(blk, wht, w);
    float sd = smoothstep(0.55, 0.85, top) * smoothstep(-0.24, -0.15, x) * smoothstep(0.03, -0.03, x);
    return mix(c, vec3(0.56, 0.58, 0.61), sd * 0.85);
  }
  if (isPart(part, 3.0) && nl.y < 0.0) return mix(wht, blk, smoothstep(0.35, 0.8, info.y + info.z * 0.35));
  return blk;
}
vec3 colDolphin(float part, vec3 r, vec4 info, vec3 nl, inout float gloss){
  gloss = 0.85;
  vec3 cape = vec3(0.25, 0.29, 0.34), flank = vec3(0.52, 0.56, 0.60), belly = vec3(0.91, 0.91, 0.90);
  if (isPart(part, 0.0)) {
    float top = info.z, x = r.x;
    float capeLine = 0.45 - 0.28 * exp(-pow((x + 0.05) / 0.12, 2.0)) + 0.10 * smoothstep(0.30, 0.42, x);
    vec3 c = mix(flank, cape, smoothstep(capeLine - 0.08, capeLine + 0.08, top));
    c = mix(belly, c, smoothstep(-0.55, -0.22, top + 0.08 * sin(x * 20.0)));
    return c * (0.95 + 0.08 * vnoise(r.xz * 30.0));
  }
  if (isPart(part, 2.0) || isPart(part, 3.0)) return nl.y > 0.0 ? cape : flank * 0.95;
  return cape;
}
vec3 colTurtle(float part, vec3 r, vec4 info, vec3 nl, inout float gloss){
  gloss = 0.5;
  if (isPart(part, 8.0)) {
    float top = info.z;
    if (top < -0.12) {
      gloss = 0.3;
      vec3 pl = vec3(0.90, 0.82, 0.60);
      float ln = min(abs(fract(r.x * 8.0 + 0.5) - 0.5) / 8.0, abs(r.z));
      return pl * mix(0.72, 1.0, smoothstep(0.0, 0.006, ln));
    }
    vec4 v = voroV(vec2(r.x * 6.2, r.z * 5.0 + 0.5));
    float ang = atan(v.y, v.x);
    float st = 0.5 + 0.5 * sin(ang * 9.0 + v.w * 20.0 + vnoise(r.xz * 30.0) * 3.0);
    vec3 brown = mix(vec3(0.30, 0.20, 0.10), vec3(0.42, 0.29, 0.14), v.w);
    vec3 amber = vec3(0.78, 0.52, 0.20);
    vec3 c = mix(brown, amber, st * smoothstep(0.05, 0.45, length(v.xy)) * 0.85);
    c = mix(vec3(0.17, 0.12, 0.07), c, smoothstep(0.02, 0.07, v.z));
    c = mix(c, vec3(0.80, 0.70, 0.50), smoothstep(0.0, -0.12, top) * 0.6);
    return c;
  }
  float sc = isPart(part, 9.0) ? 40.0 : 22.0;
  vec4 v = voroV(vec2(r.x * sc, (r.z + r.y * 0.7) * sc));
  vec3 scale = mix(vec3(0.38, 0.30, 0.17), vec3(0.52, 0.40, 0.22), v.w);
  vec3 c = mix(vec3(0.86, 0.80, 0.62), scale, smoothstep(0.03, 0.12, v.z));
