/* ====================================================================== *
 *  Water surface pass (full screen ray-cast)
 * ====================================================================== */
const CRATER_N = 12;
const surfU = Object.assign({}, SU, {
  tUnder: { value: null }, uInvVP: { value: new THREE.Matrix4() }, uW2U: { value: new THREE.Vector2(0.05, 0.05) },
  uCrat: { value: Array.from({ length: CRATER_N }, () => new THREE.Vector4()) }, uWhirl: { value: new THREE.Vector4(0, 0, 0, 0) },
  uSimTexel: { value: new THREE.Vector2(1 / 440, 1 / 440) }
