const surfMat = passMat(GLSL_COMMON + `
uniform sampler2D tUnder, tSim; uniform mat4 uInvVP; uniform vec4 uDomain; uniform vec2 uSimCell, uSimTexel, uW2U, uTargetRes;
uniform float uTime, uSun, uRain; uniform vec3 uSunDir; uniform vec4 uCrat[${CRATER_N}]; uniform vec4 uWhirl;
varying vec2 vUv;
vec3 sky(vec3 r){
  float y = max(r.y, 0.0);
  vec3 c = mix(vec3(0.80,0.90,0.97), vec3(0.26,0.53,0.90), pow(y, 0.55));
  vec2 cp = r.xz / (r.y + 0.18) * 1.3 + uTime * vec2(0.010, 0.005);
  float cl = smoothstep(0.52 - uRain*0.3, 0.86, fbm3(cp));
  c = mix(c, vec3(0.98) * (1.0 - 0.35*uRain), cl * 0.85);
  c = mix(c, vec3(0.62,0.66,0.70), uRain*0.55);
  float s = max(dot(r, uSunDir), 0.0);
  c += vec3(1.0,0.92,0.75) * pow(s, 80.0) * 0.6 * uSun;
  return c;
}
void main(){
  vec2 ndc = vUv * 2.0 - 1.0;
  vec4 a = uInvVP * vec4(ndc, -1.0, 1.0); a /= a.w;
  vec4 b = uInvVP * vec4(ndc, 1.0, 1.0); b /= b.w;
  vec3 rd = normalize(b.xyz - a.xyz);
  float t = -a.y / rd.y;
  vec3 p = a.xyz + rd * t;
  vec2 suv = (p.xz - uDomain.xy) / uDomain.zw;
  vec2 o = uSimTexel * 1.5;
  vec4 sc = texture2D(tSim, suv);
  float hl = texture2D(tSim, suv - vec2(o.x, 0.0)).r, hr = texture2D(tSim, suv + vec2(o.x, 0.0)).r;
  float hd = texture2D(tSim, suv - vec2(0.0, o.y)).r, hu = texture2D(tSim, suv + vec2(0.0, o.y)).r;
  vec2 grad = vec2(hr - hl, hu - hd) / (2.0 * uSimCell * 1.5) * 0.6;
  // whirlpool twist of the wind pattern
  vec2 wp = p.xz;
  vec2 wd = p.xz - uWhirl.xy; float wr = length(wd); float ws = uWhirl.z;
  if (ws > 0.001) {
    float ang = ws * 3.2 / (wr * 0.7 + 0.5);
    float cs = cos(ang), sn = sin(ang);
    wp = uWhirl.xy + mat2(cs, sn, -sn, cs) * wd;
