const PT_VS = `attribute float aSize; attribute float aAlpha; uniform float uPx; varying float vA;
void main(){ vec4 mv = modelViewMatrix * vec4(position, 1.0); gl_Position = projectionMatrix * mv;
  gl_PointSize = max(1.5, aSize * uPx / -mv.z); vA = aAlpha; }`;
const dropFX = pointsMesh(5000, PT_VS, `varying float vA;
void main(){ vec2 d = gl_PointCoord - 0.5; float r = length(d) * 2.0; if (r > 1.0) discard;
  float hl = smoothstep(0.55, 0.0, length(d + vec2(0.16, 0.16)) * 2.0);
