const { chromium } = require('/home/cw/git_project/beach3d-eval/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: process.env.HOME + '/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome', args: ['--use-gl=angle', '--use-angle=gl-egl'], headless: true });
  const page = await browser.newPage({ viewport: { width: 360, height: 740 }, hasTouch: true });
  const logs = []; page.on('console', m => logs.push(m.type() + ': ' + m.text())); page.on('pageerror', e => logs.push('PAGEERROR ' + e.message));
  await page.goto('http://localhost:8817/index.html');
  await page.waitForTimeout(1500);
  const ov = await page.evaluate(() => [document.documentElement.scrollWidth, innerWidth, document.getElementById('cards').scrollWidth, document.getElementById('cards').clientWidth]);
  console.log('overflow', ov);
  // drag manta card up into water
  const card = await page.$$('.card'); const bb = await card[6].boundingBox();
  await page.mouse.move(bb.x + bb.width/2, bb.y + 10); await page.mouse.down();
  for (let i = 1; i <= 10; i++) { await page.mouse.move(bb.x + bb.width/2 - i*8, bb.y - i*35); await page.waitForTimeout(30); }
  await page.screenshot({ path: '_test/i0.png' });
  const st1 = await page.evaluate(() => __reef.creatures.map(c => c.S.key + ':' + c.state));
  await page.mouse.up(); await page.waitForTimeout(400);
  const st2 = await page.evaluate(() => __reef.creatures.map(c => c.S.key + ':' + c.state));
  // grab a creature from the water
  const tgt = await page.evaluate(() => { const c = __reef.creatures.find(c => c.state === 'swim' && c.S.key === 'turtle'); const v = c.pos.clone().project(window.__cam || null); return null; });
  // tap water
  await page.mouse.click(180, 300); await page.waitForTimeout(300);
  console.log(JSON.stringify({ st1, st2 }));
  // clear
  await page.evaluate(() => __reef.tool('clear')); await page.waitForTimeout(3500);
  console.log('after clear', await page.evaluate(() => __reef.creatures.length));
  // cap test
  await page.evaluate(() => { for (let i = 0; i < 30; i++) __reef.throwFromCard(i % 7); });
  await page.waitForTimeout(200);
  console.log('cap', await page.evaluate(() => [__reef.creatures.length, __reef.creatures.filter(c => c.S.key === 'humpback').length, document.getElementById('toast').textContent]));
  await page.waitForTimeout(2500);
  await page.screenshot({ path: '_test/i1.png' });
  console.log(logs.filter(l => !l.includes('404')).slice(0, 20).join('\n'));
  await browser.close();
})();
