  // clear
  await page.evaluate(() => __reef.tool('clear')); await page.waitForTimeout(3500);
  console.log('after clear', await page.evaluate(() => __reef.creatures.length));
  // cap test
  await page.evaluate(() => { for (let i = 0; i < 30; i++) __reef.throwFromCard(i % 7); });
  await page.waitForTimeout(200);
  console.log('cap', await page.evaluate(() => [__reef.creatures.length, __reef.creatures.filter(c => c.S.key === 'humpback').length, document.getElementById('toast').textContent]));
  await page.waitForTimeout(2500);
  await page.screenshot({ path: '_test/i1.png' });
  console.log(logs.filter(l => !l.includes('404')).slice(0, 20).join('\n'));
  await browser.close();
})();
